Problem:
A furniture store builds and sells sofas and beds. Each sofa costs 6 units of wood and 8 units of time while each bed costs 5 units of wood and 10 units of time. The store has available 620 units of wood and 1055 units of time. Each bed takes an additional 5 hours of shipping time while each sofa takes 3 hours of shipping time. Since there are usually more sofas than beds, the store aims to build twice as many sofas than beds. How many of each should the store make to minimize the total shipping time?

Model and facts:
{
 "model": {
  "variables": [
   {
    "name": "sofas",
    "lower": 0.0,
    "upper": null,
    "integer": true
   },
   {
    "name": "beds",
    "lower": 0.0,
    "upper": null,
    "integer": true
   }
  ],
  "objective": {
   "sense": "min",
   "terms": [
    {
     "var": "sofas",
     "coef": 3.0
    },
    {
     "var": "beds",
     "coef": 5.0
    }
   ]
  },
  "constraints": [
   {
    "name": "wood",
    "terms": [
     {
      "var": "sofas",
      "coef": 6.0
     },
     {
      "var": "beds",
      "coef": 5.0
     }
    ],
    "sense": "<=",
    "rhs": 620.0
   },
   {
    "name": "time",
    "terms": [
     {
      "var": "sofas",
      "coef": 8.0
     },
     {
      "var": "beds",
      "coef": 10.0
     }
    ],
    "sense": "<=",
    "rhs": 1055.0
   },
   {
    "name": "sofa_bed_ratio",
    "terms": [
     {
      "var": "sofas",
      "coef": 1.0
     },
     {
      "var": "beds",
      "coef": -2.0
     }
    ],
    "sense": "==",
    "rhs": 0.0
   }
  ]
 },
 "facts": {
  "objective": 0.0,
  "values": {
   "sofas": 0.0,
   "beds": 0.0
  },
  "binding": [
   "sofa_bed_ratio"
  ],
  "slack": {
   "wood": 620.0,
   "time": 1055.0,
   "sofa_bed_ratio": 0.0
  },
  "shadow_prices": null,
  "limits": {
   "wood": {
    "dropped_improves": false,
    "loosened_improves": false
   },
   "time": {
    "dropped_improves": false,
    "loosened_improves": false
   },
   "sofa_bed_ratio": {
    "dropped_improves": false,
    "loosened_improves": null
   }
  }
 }
}
